\begin{aligned}
\mathrm{StructureData}_S(\mathcal M,U,I_C,I_F,I_R)\leftrightarrow{}&
\Bigl(\mathcal M=\{\langle0,U\rangle,\langle1,I_C\rangle,\langle2,I_F\rangle,\langle3,I_R\rangle\}
\land\mathrm{Function}(I_F,\omega,\operatorname{ran}(I_F))
\land\mathrm{Function}(I_R,\omega,\operatorname{ran}(I_R))\Bigr)\\
&\lor\exists E\subseteq U\times U\;\Bigl(\mathcal M=\langle U,E\rangle\land I_C=\varnothing
\land I_F=\{\langle n,\varnothing\rangle:n\in\omega\}\\
&\qquad\land I_R=\{\langle n,\varnothing\rangle:n\in\omega\setminus\{2\}\}
\cup\{\langle2,\{\langle\dot\in,\{a\in U^2:\langle a(0),a(1)\rangle\in E\}\rangle\}\rangle\}\Bigr).
\end{aligned}
